def parse_react_response(text: str) -> dict:
    clean_text = text.strip()
    if 'Final Answer:' in clean_text:
        ans = clean_text.split('Final Answer:', 1)[1].strip()
        return {'type': 'finish', 'output': ans}

    if 'Action:' in clean_text and 'Action Input:' in clean_text:
        part_action = clean_text.split('Action:', 1)[1]
        tool_name = part_action.split('Action Input:', 1)[0].strip()
        tool_input = part_action.split('Action Input:', 1)[1].strip()
        # 如果参数后还有换行后的内容，只取到换行或保持原样
        return {'type': 'action', 'tool': tool_name, 'tool_input': tool_input}

    return {'type': 'unknown', 'raw': clean_text}

