def execute_plan_step(plan_list: list[str], executor_func) -> dict:
    if not plan_list:
        return {'status': 'ALL_DONE', 'executed_step': None, 'remaining_plan': []}

    current_step = plan_list[0]
    res = executor_func(current_step)

    if res.get('success', False):
        return {
            'status': 'STEP_OK',
            'executed_step': current_step,
            'remaining_plan': plan_list[1:]
        }
    else:
        return {
            'status': 'STEP_FAILED',
            'executed_step': current_step,
            'remaining_plan': list(plan_list)
        }

def run_agent_pipeline(initial_input: str, agents: list) -> str:
    current = initial_input
    for agent in agents:
        current = agent.process(current)
    return current

