def hitl_gate_runner(action: dict, decision: str = 'APPROVE', override_args: dict = None) -> dict:
    if not action.get('is_dangerous', False):
        return {'status': 'PASSED', 'final_args': action.get('args', {})}

    if decision == 'REJECT':
        return {'status': 'BLOCKED', 'reason': '人工拒绝放行'}
    elif decision == 'EDIT':
        return {'status': 'MODIFIED_AND_PASSED', 'final_args': override_args or {}}
    elif decision == 'APPROVE':
        return {'status': 'PASSED', 'final_args': action.get('args', {})}
    else:
        raise ValueError(f'未知决议: {decision}')

def autonomous_analyze_agent(records: list[dict], max_return_rate: float = 20.0) -> dict:
    high_risk = []
    for r in records:
        sales = r.get('sales', 0)
        returns = r.get('returns', 0)
        rate = round((returns / max(1, sales)) * 100, 2)
        if rate > max_return_rate:
            high_risk.append(r.get('category', 'Unknown'))

    status = 'ALERT' if high_risk else 'NORMAL'
    return {
        'total_categories': len(records),
        'high_return_categories': high_risk,
        'status': status
    }
